const fs = require('fs');
const path = require('path');

const readmePath = path.join(__dirname, 'README.md');
const indexPath = path.join(__dirname, 'INDEX.md');

const lines = fs.readFileSync(readmePath, 'utf8').split(/\r?\n/);
const headings = lines.filter((line) => /^#/.test(line));

fs.writeFileSync(indexPath, headings.join('\n') + '\n', 'utf8');
console.log(`Wrote ${headings.length} headings to INDEX.md`);
